SELECT c.id, c.name, c.level, c.parent_id, CASE WHEN level < 4 AND EXISTS( SELECT 1 FROM category ca WHERE ca.parent_id = c.id LIMIT 1) THEN true ELSE false END as has_children FROM category c
AND c.name LIKE concat('%',#{name},'%')
AND c.level = #{level}
AND c.parent_id = #{parentId}
LIMIT #{current},#{size}

SELECT COUNT(*)
FROM category c


        AND c.name LIKE concat('%',#{name},'%')


        AND c.level = #{level}


        AND c.parent_id = #{parentId}
